<?php get_header(); $title=get_field('blog_archive_title','option') ?: __('Blog & Insights','alify'); $intro=get_field('blog_archive_intro','option'); $blog_rows=get_field('blog_sections','option'); ?>
<?php if (empty($blog_rows)) : ?><section class="alify-section alify-archive-intro"><div class="container"><p class="alify-eyebrow">ALIFY Studio</p><h1><?php echo esc_html($title); ?></h1><?php echo wp_kses_post($intro); ?></div></section><?php endif; ?><?php alify_render_sections('blog_sections','option'); if (get_field('blog_show_dynamic_listing','option')) : ?>
<section class="alify-section"><div class="container"><div class="row g-4 alify-card-grid"><?php if (have_posts()) : while (have_posts()) : the_post(); ?><div class="col-md-6 col-lg-4"><article class="alify-card"><?php if (has_post_thumbnail()) { the_post_thumbnail('medium',array('loading'=>'lazy')); } ?><div class="alify-card-body"><p class="alify-eyebrow"><?php echo esc_html(get_the_date()); ?></p><h2><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h2><p><?php echo esc_html(get_field('summary') ?: get_the_excerpt()); ?></p></div></article></div><?php endwhile; else : ?><p><?php esc_html_e('No posts published yet.','alify'); ?></p><?php endif; ?></div><?php the_posts_pagination(); ?></div></section><?php endif; ?><?php get_footer(); ?>
